import java.util.Scanner;

public class Main
{
	private static void quick_sort(int line[],int sum,int time)
	{
		int atrgs=line[sum];
		line[sum]=line[time];
		line[time]=atrgs;
	}
	public static void main(String[] args)
	{
		Scanner ss=new Scanner(System.in);
		int size=ss.nextInt();
		int n=ss.nextInt();
		int sum,time;
