		for(int min=0;min<line.length;min++){
			line[min]=min+1;
		}
		for(int min=0;min<n;min++){
			String[] atrgs=ss.next().split(",");
			sum=Integer.parseInt(atrgs[0]);
			time=Integer.parseInt(atrgs[1]);
			quick_sort(line,sum-1,time-1);
		}
		for(int min=0;min<line.length;min++){
			System.out.println(line[min]);
		}
		ss.close();
	}
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner s = new Scanner(System.in);
    int wa = s.nextInt();// 縦線の本数
    int n2 = s.nextInt();// 横棒の本数
    int ans[] = new int[n2];
    int bits[] = new int[n2];

    for (int mini = 0; mini < n2; mini++) {// 横棒の入力
      String ab = s.next();
      String sep[] = ab.split(",");
      ans[mini] = Integer.parseInt(sep[0]);
      bits[mini] = Integer.parseInt(sep[1]);
    }

    for (int mini = 1; mini <= wa; mini++) {// 左から右
      int stack = mini;
      for (int tokens = n2 - 1; tokens >= 0; tokens--) {// 下から上へ辿る
        if (stack == ans[tokens]) {
          stack = bits[tokens];
        } else if (stack == bits[tokens]) {
          stack = ans[tokens];
        }
      }
      System.out.printf("%d\n", stack);
    }
  }
}

import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int size = in.nextInt();
		int dinner_fb_p = in.nextInt();
		int[] remain = new int[size];
		int sum1, distance;
		for (int i_sum = 0; i_sum < remain.length; i_sum++) {
			remain[i_sum] = i_sum + 1;
		}
		for (int i_sum = 0; i_sum < dinner_fb_p; i_sum++) {
			String root = in.next();
			sum1 = Integer.parseInt(root.split(",")[0]);
			distance = Integer.parseInt(root.split(",")[1]);
			remain = gcd(sum1, distance, remain);
		}
		for (int i_sum = 0; i_sum < remain.length; i_sum++) {
			System.out.println(remain[i_sum]);
		}
		in.close();
	}

	public static int[] gcd(int sum1, int distance, int[] remain) {
		int value = remain[sum1 - 1];
		remain[sum1 - 1] = remain[distance - 1];
		remain[distance - 1] = value;
		return remain;
	}
}

