	public static void main(String[] args) {

		int doublet;
		Scanner d2 = new Scanner(System.in);
		doublet = d2.nextInt();
		int[] sumTmp = new int[doublet];
		for (int to = 0; to < doublet; to++) {
			sumTmp[to] = d2.nextInt();
		}

		seretch(sumTmp);
		getY(sumTmp);

	}

	static void seretch(int[] sumTmp) {
		for (int to = 0; to < sumTmp.length; to++) {
			System.out.print(sumTmp[to]);
			if (to != sumTmp.length-1) {
				System.out.print(" ");
			} else {
				System.out.print("\n");
			}
		}
	}

	static void inpNum(int[] sumTmp) {
		for (int to = 1; to < sumTmp.length; to++) {
			for (int currentIdx = 0; currentIdx < to; currentIdx++) {
				if (sumTmp[to] < sumTmp[currentIdx]) {
					int max_first = sumTmp[to];
					for (int seisuu = to - 1; seisuu >= currentIdx; seisuu--) {
						sumTmp[seisuu+1] = sumTmp[seisuu];
					}
					sumTmp[currentIdx] = max_first;
				}
			}
			seretch(sumTmp);
		}
	}
	static void getY(int[] sumTmp) {
		for (int to = 1; to < sumTmp.length; to++) {
			int pos = sumTmp[to];
			int currentIdx = to-1;
			while (currentIdx >= 0 && sumTmp[currentIdx] > pos) {
				sumTmp[currentIdx+1] = sumTmp[currentIdx];
				currentIdx--;
			}
			sumTmp[currentIdx+1] = pos;
			seretch(sumTmp);
		}
	}

}

