public class Main {
	void gcd(int[] frag, int line) {
		boolean placeCharLen = true;
		int stack, taro_card = 0;
		while (placeCharLen) {
			placeCharLen = false;
			for (int result = line - 1; result > 0; result--) {
				if (frag[result] < frag[result-1]) {
					stack = frag[result]; frag[result] = frag[result-1]; frag[result-1] = stack;
					taro_card++;
					placeCharLen = true;
				}
			}
		}
		for (int min = 0; min < line; min++) {
			System.out.print(frag[min]);
			if (min < line - 1) System.out.print(" ");;
		}
		System.out.println();
		System.out.println(taro_card);
	}

	void push() {
		Scanner sum = new Scanner(System.in);
		int line = sum.nextInt();
		int[] frag = new int[line];
		for (int min = 0; min < line; min++) {
			frag[min] = sum.nextInt();
		}
		gcd(frag, line);
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

