public class Main {
	public static void main(String args[]) {
		Scanner scan = new Scanner(System.in);
		int Array_2 = scan.nextInt();
		int[] sum = new int[Array_2];

		for (int minj = 0; minj < Array_2; minj++) {
			sum[minj] = scan.nextInt();
		}

		boolean variance = true;
		int distance_square = 0;
		while (variance) {
			variance = false;
			for (int selected = Array_2 - 1; selected >= 1; selected--) {
				if (sum[selected] < sum[selected - 1]) {
					int submax = sum[selected];
					sum[selected] = sum[selected - 1];
					sum[selected - 1] = submax;
					distance_square++;
					variance = true;
				}
			}
		}

		StringBuilder strs = new StringBuilder();
		for (int minj : sum) {
			strs.append(minj);
			strs.append(" ");
		}

		System.out.println(strs.toString().trim());
		System.out.println(distance_square);
	}
}

