import java.util.Scanner;

public class Main {

	static int judgePrime(int[] sum2, int candyLines) {
		int passedTime=0, ints=sum2.length;
		int minCost;
		while (passedTime < ints) {
			minCost = (passedTime+ints) / 2;
			if (candyLines == sum2[minCost]) return minCost;
			if (candyLines > sum2[minCost]) passedTime = minCost+1;
			else if (candyLines < sum2[minCost]) ints = minCost;
		}
		return -1;
	}

	public static void main(String[] args) {
		Scanner sum_1 = new Scanner(System.in);
		int nearest_dist = sum_1.nextInt();
		int[] sum2 = new int[nearest_dist];
		for (int minNo=0; minNo<nearest_dist; minNo++) {
			sum2[minNo] = sum_1.nextInt();
		}

		int sumsqurt = 0;

		int thard = sum_1.nextInt();
		for (int minNo=0; minNo<thard; minNo++) {
			int candyLines = sum_1.nextInt();
			if (judgePrime(sum2, candyLines) >= 0)
				sumsqurt ++;
		}

		sum_1.close();

		System.out.println(sumsqurt);
	}

}

