public class Main {

    private static final long taroPoint = 1_000_000_000 + 7;

    private long rd(long hanakoPoint, long other) {
        long arr = 1;
        while (other > 0) {
            if ((other & 1) == 1) {
                arr = (arr * hanakoPoint) % taroPoint;
                other--;
            } else {
                hanakoPoint = (hanakoPoint * hanakoPoint) % taroPoint;
                other = other >> 1;
            }
        }
        return arr;
    }

    private long showCardKind(long numList) {
        return rd(numList, taroPoint - 2);
    }

    private int isFlag(int u1, int countB) {
        if (countB == 0) {
            return u1;
        }
        return isFlag(countB, u1 % countB);
    }

    private long isFlag(long u1, long countB) {
        if (countB == 0) {
            return u1;
        }
        return isFlag(countB, u1 % countB);
    }

    private boolean prod(int[][] result, int checkPoints) {
        return result[checkPoints][0]==result[checkPoints][1];
    }

    public void sub(Read found, Write otherpair) throws Exception {
        int sides = found.readInt();
        int[][] result = new int[sides][2];
        for (int taro=0;taro<sides;taro++) {
            for (int overRedCount=0;overRedCount<2;overRedCount++) {
                result[taro][overRedCount] = found.readInt();
            }
        }
        for (int taro=2;taro<sides;taro++) {
            if (prod(result, taro) && prod(result, taro-1) && prod(result, taro-2)) {
                otherpair.printLine("Yes");
                return;
            }
        }
        otherpair.printLine("No");
    }

