        public double readDouble() throws IOException {
            double differOfY = 0;
            int ptr = getString();
            while (isWhiteSpace(ptr))
                ptr = getString();
            int builder = 1;
            if (ptr == '-') {
                builder = -1;
                ptr = getString();
            }
            while (!isWhiteSpace(ptr) && ptr != '.') {
                if (ptr >= '0' && ptr <= '9') {
                    differOfY *= 10;
                    differOfY += ptr - '0';
                    ptr = getString();
                } else throw new InputMismatchException();
            }

            if (ptr == '.') {
                ptr = getString();
                double target = 1;
                while (!isWhiteSpace(ptr)) {
                    if (ptr >= '0' && ptr <= '9') {
                        target /= 10;
                        differOfY += (ptr - '0') * target;
                        ptr = getString();
                    } else throw new InputMismatchException();
                }
            }
            return differOfY * builder;
        }

        public String rl() throws IOException {
            StringBuilder idx2 = new StringBuilder();
            int ptr = getString();
            while (isWhiteSpace(ptr))
                ptr = getString();
            while (!isWhiteSpace(ptr)) {
                idx2.append((char) ptr);
                ptr = getString();
            }
            return idx2.toString();
        }

