import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner tokenizer = new Scanner(System.in);
        int max = tokenizer.nextInt();
        int total = tokenizer.nextInt();

        ArrayList<Integer> rightMostAscendingOrderIndex = new ArrayList<>();
        ArrayList<Integer> rate = new ArrayList<>();

        for (int cui = 0; cui < total; cui++) {
            int tMinute = tokenizer.nextInt();
            if (tMinute < max) {
                rightMostAscendingOrderIndex.add(tMinute);
            } else {
                rate.add(tMinute);
            }
        }

        tokenizer.close();

        Collections.sort(rightMostAscendingOrderIndex);
        Collections.reverse(rightMostAscendingOrderIndex);
        Collections.sort(rate);

        int shiken2 = -1;
        int currentProcess = -1;
        for (int cui = 0; cui < rightMostAscendingOrderIndex.size(); cui++) {
            if (max - 1 - cui != rightMostAscendingOrderIndex.get(cui)) {
                shiken2 = max - 1 - cui;
                break;
            }
        }

        for (int cui = 0; cui < rate.size(); cui++) {
            if (max + cui != rate.get(cui)) {
                currentProcess = max + cui;
                break;
            }
        }

        if (rate.size() > 0 && rightMostAscendingOrderIndex.size() > 0) {
            if (shiken2 == -1) {
                shiken2 = rightMostAscendingOrderIndex.get(rightMostAscendingOrderIndex.size() - 1) - 1;
            }
            if (currentProcess == -1) {
                currentProcess = rate.get(rate.size() - 1) + 1;
            }

            if (max - shiken2 < currentProcess - max) {
                System.out.println(shiken2);
            } else if (max - shiken2 > currentProcess - max) {
                System.out.println(currentProcess);
            } else {
                System.out.println(shiken2);
            }
        } else if (rate.size() == 0) {
            System.out.println(max);
        } else if (rightMostAscendingOrderIndex.size() == 0) {
            if (rate.contains(max)) {
                System.out.println(max - 1);
            } else {
                System.out.println(max);
            }
        }

    }
}

