import java.util.Arrays;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner data = new Scanner(System.in);
        int step = data.nextInt();
        int checkPoints = data.nextInt();
        int stdIn[] = new int[checkPoints];
        int pattern[] = new int[checkPoints];
        for (int splits = 0; splits < checkPoints; splits++) {
            stdIn[splits] = data.nextInt();
        }

        bubbleSort(stdIn, pattern, step, checkPoints);
        Arrays.sort(pattern);

        System.out.println(pattern[0]);

        data.close();
    }

    public static void bubbleSort(int stdIn[], int pattern[], int step, int checkPoints) {
        for (int splits = 0; splits < checkPoints; splits++) {
            if (splits == 0) {
                pattern[splits] = linearSearch(stdIn[checkPoints - 1] - stdIn[0], stdIn[0] + step - stdIn[1]);
            } else if (splits == checkPoints - 1) {
                pattern[splits] = linearSearch(stdIn[checkPoints - 1] - stdIn[0], stdIn[checkPoints - 2] + step - stdIn[checkPoints - 1]);
            } else {
                pattern[splits] = linearSearch(step - (stdIn[splits] - stdIn[splits - 1]), step - (stdIn[splits + 1] - stdIn[splits]));
            }
        }
    }

    public static int linearSearch(int mod, int h) {
        if (mod >= h) {
            return h;
        } else {
            return mod;
        }
    }
}

