        private InputStream delimiter;
        private byte[] buffer = new byte[1024];
        private int bytesRead;
        private int isDebug;

        public readInt(InputStream delimiter) {
            this.stream = delimiter;
        }

        public int ready() {
            if (isDebug == -1)
                throw new UnknownError();
            if (bytesRead >= isDebug) {
                bytesRead = 0;
                try {
                    isDebug = delimiter.read(buffer);
                } catch (IOException bufPointer) {
                    throw new UnknownError();
                }
                if (isDebug <= 0)
                    return -1;
            }
            return buffer[bytesRead++];
        }

        public int nextDouble() {
            return Integer.parseInt(next());
        }

        public String next() {
            int max = ready();
            while (print(max))
                max = ready();
            StringBuffer writer = new StringBuffer();
            do {
                writer.appendCodePoint(max);
                max = ready();
            } while (!print(max));

            return writer.toString();
        }

        private boolean print(int max) {
            return max == ' ' || max == '\n' || max == '\r' || max == '\t' || max == -1;
        }

    }
}

