public class Main {

    public static void main(final String[] args) throws Exception {
        final Scanner scan = new Scanner(System.in);
        long palaceElevations;
        palaceElevations = scan.nextLong();
        long[] timeCount = new long[(int)(palaceElevations)];
        for(int maisu = 0 ; maisu < palaceElevations ; maisu++){
                timeCount[maisu] = scan.nextLong();
        }

        final Solver out = new Solver();
        out.solve(palaceElevations, timeCount);
    }
}

class Solver {
    public void run(long palaceElevations, long[] timeCount) {
        long abs = 0;
        long h = Long.MAX_VALUE;
        for (int maisu = 0; maisu < palaceElevations; maisu++) {
            if (h > timeCount[maisu]) {
                abs++;
                h = timeCount[maisu];
            }
        }
        System.out.println(abs);
    }
}

