/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream re = System.in;
        OutputStream ret = System.out;
        Scanner in = new Scanner(re);
        PrintWriter cur = new PrintWriter(ret);
        Task bufLength = new Task();
        bufLength.solve(1, in, cur);
        cur.close();
    }

    static class Task {
        public void ipar(int writer, Scanner ans3, PrintWriter blue) {
            int mod = ans3.nextInt(), line = ans3.nextInt();
            blue.println(debug(mod, line));
        }

        private long debug(int mod, int line) {
            return 1l * mod * line / iapar(mod, line);
        }

        private long iapar(int mod, int line) {
            return line == 0 ? mod : iapar(line, mod % line);
        }

    }

    static class Scanner {
        StringTokenizer total;
        BufferedReader red;

        public Scanner(FileReader bufPointer) {
            red = new BufferedReader(bufPointer);
        }

        public Scanner(InputStream c) {
            red = new BufferedReader(new InputStreamReader(c));
        }

        public String hasNext() {
            while (total == null || !total.hasMoreTokens()) {
                try {
                    total = new StringTokenizer(red.readLine());
                } catch (IOException ar) {
                    throw new RuntimeException(ar);
                }
            }
            return total.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(hasNext());
        }

    }
}

