public class Main {

	public static void main(String[] args) {
		Scanner D1 = new Scanner(System.in);
		long div = Long.parseLong(D1.next());
		long k = Long.parseLong(D1.next());
		D1.close();

		// ユークリッドの互除法
		long a4 = div;
		long distance = k;
		if (div < k) {
			a4 = k;
			distance = div;
		}
		long out = a4 % distance;
		while (out != 0) {
			a4 = distance;
			distance = out;
			out = a4 % distance;
		}
		long calc = div * k;
		System.out.println(calc / distance);
	}
}

