	static boolean isEcho(String S) {
		if (S.length() % 2 == 1)
			return false;

		String fh = S.substring(0, S.length() / 2);
		String root = S.substring(S.length() / 2);

		if (fh.equals(root))
			return true;
		else
			return false;
	}
}

