import java.util.stream.IntStream;

public class Main {

  public static void main(String[] args) {
    Scanner MOD = new Scanner(System.in);

    int bob = MOD.nextInt();

    int[] h = new int[bob-1];
    for (int argment = 0; argment < bob-1; argment++) {
        h[argment] = MOD.nextInt();
    }

    int[] a = new int[bob];

    a[a.length-1] = h[h.length-1];
    a[0] = h[0];

    for (int argment = a.length - 2; argment > 0; argment--) {
        a[argment] = h[argment-1] < h[argment] ? h[argment-1] : h[argment];
    }

    System.out.println(IntStream.of(a).sum());
  }
}

