class P2 {
    static void outn() {
        final Scanner s2 = new Scanner(System.in);
        final int ans = s2.nextInt();
        final int card = s2.nextInt();
        final int ar = calcsumo(ans, card);
        System.out.println(ar);
    }

    static int calcsumo(final int ans, final int card) {
        final int other = ans - 1;
        final int tMinute = card - 1;
        final int max = tMinute / other;
        if (tMinute - (other * max) > 0) {
            return max + 1;
        }
        return max;
    }
}

