    static int calcsumo(final String cardCount, final String kekka) {
        int ar = 0;
        for (int hi = 0; hi < 3; hi++) {
            if (Objects.equals(cardCount.charAt(hi), kekka.charAt(hi))) {
                ar++;
            }
        }
        return ar;
    }
}

