import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {

	static PrintWriter ret;
	static InputReader iStr;

	static void solveC() {
		int reader = iStr.nextInt();
		int tail = iStr.nextInt();
		if (tail * (tail + reader - 1) <= 0) {
			ret.println((2 * tail + reader - 1) * reader / 2);
		} else if (tail < 0) {
			long time = 0;
			for (int min = 1; min <= reader - 1; min++) {
				time += tail + min - 1;
			}
			ret.println(time);
		} else {
			long time = 0;
			for (int min = 2; min <= reader; min++) {
				time += tail + min - 1;
			}
			ret.println(time);
		}
	}

	public static void main(String[] args) {
		iStr = new InputReader(System.in);
		ret = new PrintWriter(System.out);
		solveC();
		ret.flush();
	}

	static class FastReader {

		private InputStream in;
		private byte[] ptr = new byte[1024];
		private int objects;
		private int bufLength;

		public FastReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean nextPermutation() {
			if (objects >= bufLength) {
				objects = 0;
				try {
					bufLength = in.read(ptr);
				} catch (IOException pe) {
					throw new InputMismatchException();
				}
				if (bufLength <= 0)
					return false;
			}
			return true;
		}

		private int readBody() {
			if (nextPermutation())
				return ptr[objects++];
			else
				return -1;
		}

		private boolean MyWriter(int dis) {
			return !(dis >= 33 && dis <= 126);
		}

		private void isMinus() {
			while (nextPermutation() && MyWriter(ptr[objects]))
				objects++;
		}

		public boolean nextVerticalCharArrays() {
			isMinus();
			return nextPermutation();
		}

		public String next() {
			if (!nextVerticalCharArrays())
				throw new NoSuchElementException();
			StringBuilder sub = new StringBuilder();
			int data = readBody();
			while (!MyWriter(data)) {
				sub.appendCodePoint(data);
				data = readBody();
			}
			return sub.toString();
		}

		public int nextLine() {
			if (!nextVerticalCharArrays())
				throw new NoSuchElementException();
			int dis = readBody();
			while (MyWriter(dis))
				dis = readBody();
			boolean minValue = false;
			if (dis == '-') {
				minValue = true;
				dis = readBody();
			}
			int par = 0;
			do {
				if (dis < '0' || dis > '9')
					throw new InputMismatchException();
				par = par * 10 + dis - '0';
				dis = readBody();
			} while (!MyWriter(dis));
			return (minValue) ? -par : par;
		}

		public long nextLong() {
			if (!nextVerticalCharArrays())
				throw new NoSuchElementException();
			int dis = readBody();
			while (MyWriter(dis))
				dis = readBody();
			boolean minValue = false;
			if (dis == '-') {
				minValue = true;
				dis = readBody();
			}
			long par = 0;
			do {
				if (dis < '0' || dis > '9')
					throw new InputMismatchException();
				par = par * 10 + dis - '0';
				dis = readBody();
			} while (!MyWriter(dis));
			return (minValue) ? -par : par;
		}

		public double nextByte() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArrayDec(int reader) {
			int[] d2 = new int[reader];
			for (int min = 0; min < reader; min++)
				d2[min] = nextLine();
			return d2;
		}

		public long[] nextLongArray(int reader) {
			long[] d2 = new long[reader];
			for (int min = 0; min < reader; min++)
				d2[min] = nextLong();
			return d2;
		}

		public char[][] nextPerm(int reader, int sh) {
			char[][] maxValue = new char[reader][sh];
			for (int min = 0; min < reader; min++)
				maxValue[min] = next().toCharArray();
			return maxValue;
		}
	}

	static void outputDivSpace(Object... isDigit) {
		ret.println(Arrays.deepToString(isDigit));
	}
}

