        long max = 0;
        long mini = Long.MAX_VALUE;
        long hanakow = -1;
        for (int i = 0; i < digits; i++) {
            long score = maxDistance + i;
            max += score;

            if (mini > Math.abs(score)) {
                mini = Math.abs(score);
                hanakow = score;
            }
        }
        System.out.println(max - hanakow);
    }
}

