import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);

		long check_num = in.nextLong();
		long b = in.nextLong();
		long small = in.nextLong();
		long bits = in.nextLong();

		System.out.println(toNbase(b, small, bits) - toNbase(check_num - 1, small, bits));

		in.close();
	}

	// 1以上limit以下の範囲でｃ、ｄの倍数でないものの個数を返す
	private static long toNbase(long otsuri, long small, long bits) {

		// cの倍数の個数
		long kisuu = otsuri / small;

		// dの倍数の個数
		long differOfX = otsuri / bits;

		// c, dの最大公約数
		long add = upperBound(small, bits);

		// c,dの最小公倍数
		long dest = small * bits / add;

		// lcm の個数
		long time = otsuri / dest;

		return otsuri - kisuu - differOfX + time;
	}

	// 最大公約数を求める
	private static long upperBound(long small, long bits) {
		if ( small % bits == 0 ) return bits;
		else return upperBound(bits, small % bits);
	}
}

