		value = str_ary/func(sb,count,convertToLong(sb,count));
		long bcnt = str_ary - (charn + option1) + value;

		charn = (tmp-1)/sb;
		option1 = (tmp-1)/count;
		value = (tmp-1)/func(sb,count,convertToLong(sb,count));
		long input = (tmp-1) - (charn + option1) + value;

		System.out.println(bcnt - input);
	}

	static long convertToLong(long tmp, long str_ary) {
		if(tmp%str_ary == 0) return str_ary;
		return convertToLong(str_ary,tmp%str_ary);
	}

	static long func(long tmp,long str_ary,long m) {
		return tmp * str_ary / m;
	}

	public static void main(String[] args) {
		new Main().doIt();
	}

}

