import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);

        long a = s.nextLong();
        long max = s.nextLong();
        long calc = s.nextLong();
        long card = s.nextLong();

        long ans = Main(max, calc, card) - Main(a-1, calc, card);

        System.out.println(ans);
    }

    static long findSumOfDigits(long a, long max) {
        if (max == 0)
            return a;
        return findSumOfDigits(max, a % max);
    }

    static long Main(long n1, long calc, long card) {
        long ichiman = n1;
        ichiman -= n1 / calc;
        ichiman -= n1 / card;
        long tmpc2 = calc / findSumOfDigits(calc, card) * card;
        ichiman += n1 / tmpc2;
        return ichiman;
    }
}

