public class Main {
    static ArrayList<trip> past;
    public static void main(String[] args){
        try{
            BufferedReader index=new BufferedReader(new InputStreamReader(System.in));
            String[] memo=index.readLine().split(" ");
            int AStr=Integer.parseInt(memo[0]);
            int count=Integer.parseInt(memo[1]);
            memo=index.readLine().split(" ");
            int[] line1=new int[AStr];
            int k=0;
            int process=0;
            for(int alphabet=0;alphabet<AStr;alphabet++){
                line1[alphabet]=Integer.parseInt(memo[alphabet]);
                k+=line1[alphabet];
                if(k<=count){
                    process++;
                }
            }
            System.out.println(process+1);

        }catch(Exception binary){
            System.out.println("KKKK "+binary.getMessage());
        }
    }

    static class run{
        int high,horizonLineList,test;
        public run(int high,int horizonLineList,int test){
            this.lev=high;
            this.node=horizonLineList;
            this.child=test;
        }
    }
    static void bfs(ArrayList<ArrayList<Integer>> st){
        Queue<trip> cnt=new ArrayDeque<>();
        cnt.add(new trip(0,0,st.get(0).size()));
        boolean[] verLineNum=new boolean[st.size()];
        verLineNum[0]=true;
        while(cnt.size()>0){
            trip arr1=cnt.poll();
            if(arr1.child==0) {
                past.add(arr1);
            }

            int horizonLineList=arr1.node;
            for(int alphabet=0;alphabet<st.get(horizonLineList).size();alphabet++){
                int rProcess=st.get(horizonLineList).get(alphabet);
                if(!verLineNum[rProcess]){
                    cnt.add(new trip(arr1.lev+1,rProcess,st.get(rProcess).size()));
                    verLineNum[rProcess]=true;
                }
            }
        }
    }
    static void getTIme(int[] goalNum) {
        Random param = new Random();
        for (int alphabet = 0; alphabet < goalNum.length; alphabet++) {
            int intAry = param.nextInt(goalNum.length);
            int level = goalNum[alphabet];
            goalNum[alphabet] = goalNum[intAry];
            goalNum[intAry] = level;
        }
    }
}

