    Scanner digit = new Scanner(System.in);

    int target = digit.nextInt();

    int[] Bob = new int[target];    
    for (int l = 0; l < target; l++) {
      Bob[l] = digit.nextInt();
    }

    int sumAll = 2147483647;
    for (int l = 0; l < target-1; l++) {
      int c = 0;
      int stdIn = 0;
      for (int j = 0; j <= l; j++) {
        c += Bob[j];
      }
      for (int j = l + 1 ; j < target ; j++) {
        stdIn += Bob[j];
      }
      if (c < stdIn) {
        if (sumAll > stdIn - c) {
          sumAll = stdIn -c ;
        }
      } else {
        if ( sumAll > c - stdIn) {
          sumAll = c - stdIn;
        }
      }
    }

    System.out.println(sumAll);

  }
}

