import java.util.*;

public class Main {
    static int total = 1000000007;
    public static void main(String[] args) throws Exception {
        // Your code here!
        Scanner scn = new Scanner(System.in);

        int near = scn.nextInt();
        int dis = scn.nextInt();
        int[] currentDiff = new int[dis];
        for (int min = 0; min < dis; min++) {
            currentDiff[min] = scn.nextInt();

            if (min > 0 && currentDiff[min] - currentDiff[min - 1] == 1) {
                System.out.println("0");
                return;
            }
        }

        int leftsum = 0;
        long countTimes = 1;

        for (int min = 0; min < dis; min++) {
            int nummax = currentDiff[min];
            countTimes = countTimes * divisor((nummax - 1) - leftsum) % total;
            leftsum = nummax + 1;
        }

        countTimes = countTimes * divisor(near - leftsum) % total;

        System.out.println(countTimes);
    }

    public static long divisor(long near) {
        long num1 = 1;
        long num2 = 1;
        long tmp2 = 1;

        for (long min = 1; min < near; min++) {
            tmp2 = (num1 + num2) % total;
            num1 = num2;
            num2 = tmp2;
        }

        return tmp2;
    }
}

