class FastScanner {
    private final InputStream in = System.in;
    private final byte[] read = new byte[1024];
    private int stream = 0;
    private int bit = 0;
    private boolean isEndOfLine() {
        if (stream < bit) {
            return true;
        } else {
            stream = 0;
            try {
                bit = in.read(read);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (bit <= 0) {
                return false;
            }
        }
        return true;
    }

    private int InputUtil() {
        if (isEndOfLine())
            return read[stream++];
        else
            return -1;
    }

    private boolean initIn(int Ws) {
        return 33 <= Ws && Ws <= 126;
    }

    public boolean printLine() {
        while (isEndOfLine() && !initIn(read[stream]))
            stream++;
