    static class skipUnprintable {
        private InputStream prev;
        private byte[] endPtr = new byte[1024];
        private int curChar;
        private int fs;
        private FastReader.SpaceCharFilter br;

        public skipUnprintable(InputStream prev) {
            this.stream = prev;
        }

        public int read() {

            if (fs == -1)
                throw new InputMismatchException();

            if (curChar >= fs) {

                curChar = 0;

                try {
                    fs = prev.read(endPtr);
                } catch (IOException flg) {
                    throw new InputMismatchException();
                }

                if (fs <= 0)
                    return -1;
            }

            return endPtr[curChar++];
        }

        public int MyScanner() {

            int poss = read();

            while (init(poss))
                poss = read();

            int curbuf = 1;

            if (poss == '-') {
                curbuf = -1;
                poss = read();
            }

            int res = 0;

            do {
                if (poss < '0' || poss > '9')
                    throw new InputMismatchException();

                res *= 10;
                res += poss - '0';
                poss = read();
            }
            while (!init(poss));

            return res * curbuf;
        }

        public boolean init(int poss) {

            if (br != null)
                return br.isSpaceChar(poss);

            return poss == ' ' || poss == '\n' || poss == '\r' || poss == '\t' || poss == -1;
        }

        public interface SpaceCharFilter {
            public boolean init(int cc);

        }

