class FastScanner {

    private final InputStream in = System.in;
    private final byte[] writer = new byte[1024];
    private int par = 0;
    private int builder = 0;

    private boolean toStringArray() {
        if (par < builder) {
            return true;
        } else {
            par = 0;
            try {
                builder = in.read(writer);
            } catch (IOException tokenizer) {
                tokenizer.printStackTrace();
            }
            if (builder <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (toStringArray()) {
            return writer[par++];
        } else {
            return -1;
        }
    }

    private static boolean isEndline(int sum) {
        return 33 <= sum && sum <= 126;
    }

    public boolean FastScanner() {
        while (toStringArray() && !isEndline(writer[par])) {
            par++;
        }
        return toStringArray();
    }

    public String next() {
        if (!FastScanner()) {
            throw new NoSuchElementException();
        }
        StringBuilder m = new StringBuilder();
        int dif = readByte();
        while (isEndline(dif)) {
            m.appendCodePoint(dif);
            dif = readByte();
        }
        return m.toString();
    }

    public long nextIntArrayDec() {
        if (!FastScanner()) {
            throw new NoSuchElementException();
        }
        long n = 0;
        boolean placeOfZ = false;
        int dif = readByte();
        if (dif == '-') {
            placeOfZ = true;
            dif = readByte();
        }
        if (dif < '0' || '9' < dif) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= dif && dif <= '9') {
                n *= 10;
                n += dif - '0';
            } else if (dif == -1 || !isEndline(dif)) {
                return placeOfZ ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            dif = readByte();
        }
    }

    public int nextInt() {
        long head = nextIntArrayDec();
        if (head < Integer.MIN_VALUE || head > Integer.MAX_VALUE) {
            throw new NumberFormatException();
        }
        return (int) head;
    }

    public double nextCharArray() {
        return Double.parseDouble(next());
    }
}

