/*
 * 0を区切りに1以上が続く区間をスタックで管理しようとしたが、よく分からなくなり断念。
 * 方針を以下に変更
 * ①0が出てくるまで、目標の高さを先頭からマイナス1する
 * ②0が出てきた場合、先頭に戻る。
 *   ただし、1以上の区間に遭遇していない(先頭から連続する0の区間の場合) 例:[0,0,0,0,2,2,3]とか
 *   場合は先頭に戻らない
 * ③終了条件を満たすまで①、②を繰り返す。
 *   ⇒目標の高さが全て0になったら終了
 */

import java.util.Scanner;
class Main{
  public static void main(String[] args) {
    Main base = new Main();
    base.run();
  }
  private void getDivisors() {

    Scanner ma = new Scanner(System.in);
    int dbTableC = ma.nextInt();
    int[] serialVersionUID = new int[dbTableC];
    int total = 0;
    for(int S=0; S<dbTableC; S++) {
      serialVersionUID[S] = ma.nextInt();
    }

    boolean line = true;
    while(line){
      //out(ary);

      // 終了条件
      line = false;
      for(int S=0; S<dbTableC; S++) {
        if(serialVersionUID[S] > 0 ) {
          line = true;
          break;
        }
      }
      boolean people = true;
      for(int S=0; S<dbTableC; S++) {

        // 先頭の0を読み飛ばす
        if(serialVersionUID[S] <= 0 && people) {
          continue;
        }

        // 1以上の区間をマイナス1する。1以上の区間が終わったらブレイク。
        if(serialVersionUID[S] <= 0) break;
        serialVersionUID[S]--;
        people = false;
      }
      // カウントアップ
      if (!people) total++;

    }
    System.out.println(total);
  }
//  private void out(int[] pary) {
//	  for(int i : pary)
//		  System.out.print(i + " ");
//	  System.out.println();
//  }
}

