import java.util.Arrays;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		Scanner start = new Scanner(System.in);
		int[]swp=new int[start.nextInt()];
		int height=start.nextInt();
		for(int i=0;i<swp.length;i++)swp[i]=start.nextInt();
		System.out.println(solve(swp, height));

	}

	public static int solve(int[]swp, int height) {
		int[]count=new int[swp.length];
		Arrays.fill(count, Integer.MAX_VALUE);
		count[0]=0;
		for(int i=1;i<swp.length;i++) {
			for(int stoneHeights=1;stoneHeights<=height;stoneHeights++) {
				count[i]=Math.min(count[i], i-stoneHeights>=0?(count[i-stoneHeights]+Math.abs(swp[i]-swp[i-stoneHeights])):Integer.MAX_VALUE);
			}
		}
		return count[count.length-1];
	}


}

