class Main {

    static int[] maxDis;
    static int[] dp;
    static int remainPowser, time;

    static int binarySearch(int start, int value)
    {
        //base cases
        if(value-start<=0)
			return 0;
		if(value-start==1)
		    return Math.abs(maxDis[value]-maxDis[start]);


        if(dp[start]==-1)
        {
            int twoDownStep = Integer.MAX_VALUE;
            for(int maisu = 1; maisu<=time; maisu++)
            {   
                if(start + maisu<=remainPowser - 1)
                    twoDownStep = Math.min(twoDownStep, binarySearch(start + maisu, value) + Math.abs(maxDis[start] - maxDis[start + maisu]));
            }
            dp[start] = twoDownStep;
            return twoDownStep;
        }
        else
            return dp[start];
    }

