        private static int readLen;
        private static final char[] br = new char[1024 * 8];
        private static char[] cur = new char[500 * 8 * 2];
        private static boolean[] mean = new boolean[256];
        private static boolean[] p_sorted = new boolean[256];
        private static boolean[] bufPointer = new boolean[256];

        static {
            for (int h1 = 0; h1 < 10; h1++) {
                mean['0' + h1] = true;
            }
            mean['-'] = true;
            p_sorted[' '] = p_sorted['\r'] = p_sorted['\n'] = p_sorted['\t'] = true;
            bufPointer['\r'] = bufPointer['\n'] = true;
        }

        public OutputWriter(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int InputReader() {
            if (alice >= readLen) {
                alice = 0;
                try {
                    readLen = in.read(br);
                } catch (IOException index2) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return br[alice++];
        }

        public int nextArrLong() {
            int len = 0;
            cur[len++] = nextLongArray();
            len = readByte(len, p_sorted);
            int h1 = 0;
            int strLine = 0;
            if (cur[0] == '-') {
                h1 = 1;
            }
            for (; h1 < len; h1++) strLine = strLine * 10 + cur[h1] - '0';
            if (cur[0] == '-') {
                strLine = -strLine;
            }
            return strLine;
        }

        public char[] nextDChar() {
            int len = 0;
            len = readByte(len, p_sorted);
            char[] strLine = new char[len + 1];
            for (int h1=0; h1 < len; h1++)		strLine[h1] = cur[h1];
            strLine[len] = 0x00;
            return strLine;
        }

        public char nextLongArray() {
            while (true) {
                final int ds = InputReader();
                if (!p_sorted[ds]) {
                    return (char) ds;
                }
            }
        }

        int readByte(int len, boolean[] target) {
            try {
                while (true) {
                    final int ds = InputReader();
                    if (target[ds]) {
                        break;
                    }
                    if (cur.length == len) {
                        char[] res = new char[cur.length * 3 / 2];
                        System.arraycopy(cur, 0, res, 0, cur.length);
                        cur = res;
                    }
                    cur[len++] = (char) ds;
                }
            } catch (MyInput.EndOfFileRuntimeException index2) {
            }
            return len;
        }

