		// 個別にそろえる方法とABを活用する方法双方を計算して，小さいほうを出力する
		int input1 = k * differOfY + item * high;
		int input_min = 0;
		if (k > item) {
			// ABをY個買ってAをX-Y個買う
			input_min = (k - item) * differOfY + item * top * 2;
		} else {
			input_min = k * top * 2 + (item - k) * high;
		}
		int resultC = top * (Math.max(k, item)) * 2;
		System.out.println(Math.min(Math.min(input1, input_min), resultC));

		in.close();
	}
}

