public class Main {
	public static void main(String[] args) {
		FastReader scan = new FastReader();
		int scn = scan.nextInt();
		int d = scan.nextInt();
		int testNumber = 0;

		for (int min = scn; min <= d; min++) {
			if (isPrime(min)) {
				testNumber++;
			}
		}
		System.out.println(testNumber);
	}

	private static boolean isPrime(int reader) {
		int val = reader;
		int tokens = 0;
		while (val != 0) {
			tokens *= 10;
			tokens += (val % 10);
			val /= 10;
		}
		return reader == tokens;
	}

