public class Main {
    static boolean loop(int max) {
        String zero = Integer.toString(max);
        int score =0;
        if(zero.length()%2==0){
            score = zero.length()/2;
        }
        else {
            score = (zero.length()- 1) / 2;
        }
        boolean base = true;
        for (int grid = 0; grid < score; grid++) {
            if (zero.charAt(grid) != zero.charAt(zero.length() - grid - 1)) {
                base = false;
                break;
            }
        }
        return base;
}
    public static void main(String[] args) {
        Scanner a0 = new Scanner(System.in);
        int max = a0.nextInt();
        int en = a0.nextInt();
        int remainLengths = 0;
        for (int grid = max; grid <= en; grid++) {
            if (loop(grid))
                remainLengths++;
        }
        System.out.println(remainLengths);
    }
}

