        Scanner cur = new Scanner(System.in);
        int preferableTmp = cur.nextInt();

        int lastT = 0;
        int fthousand = 0;
        int m = 0;
        int preY = 0;
        int target = 0;

        for(int tmp2=preferableTmp; tmp2>0; tmp2--) {
            if(preferableTmp == 1) {
                preY = 1;
                break;
            }
            if(tmp2 % 2 == 0) {
                target = tmp2;
                m = tmp2;
                while(true) {
                    if(target % 2 != 0) {
                        break;
                    } else {
                        lastT += 1;
                        target /= 2;
                    }
                }
                if(fthousand < lastT) {
                    fthousand = lastT;
                    preY = m;
                }
                lastT = 0;
            }
        }
        System.out.println(preY);
    }
}

